INSERT OR IGNORE INTO submissions (id, type, full_name, email, phone, subject, message, is_approved, status, created_at) VALUES ('sub-test-1', 'testimony', 'Chidinma Nwosu', 'chidinma@example.org', '', 'Peace and Restoration in Family', 'After joining the midweek intercession and standing on the monthly prophetic focus, our family experienced complete restoration and open doors in Toronto.', 1, 'reviewed', '2026-11-22T22:51:05.576Z');
INSERT OR IGNORE INTO submissions (id, type, full_name, email, phone, subject, message, is_approved, status, created_at) VALUES ('sub-test-2', 'testimony', 'David Mensah', 'david.m@example.org', '', 'Healing and Career Breakthrough', 'I followed the daily devotionals faithfully every morning before work in Sydney. Within three months I recovered completely from chronic illness and stepped into a leadership role.', 1, 'reviewed', '2026-11-22T22:51:05.576Z');
INSERT OR IGNORE INTO submissions (id, type, full_name, email, phone, subject, message, is_approved, status, created_at) VALUES ('sub-test-3', 'testimony', 'Grace Akinola', 'grace.a@example.org', '', 'Graduating from the Bible Academy', 'Completing the Foundation & Leadership cohort transformed how I study Scripture and serve in our local fellowship cell.', 1, 'reviewed', '2026-11-22T22:51:05.576Z');
